yakit.AutoInitYakit()

# Input your code!

domains = cli.Text("domains",cli.setRequired(true))
domains = str.ParseStringToLines(domains)
thread = cli.Int("thread",cli.setDefault(1))
cli.check()

wg := sync.NewSizedWaitGroup(thread)

yakit.EnableTable("whois", ["域名","注册时间","过期时间","NS服务器"])
outputTable = func(domain,startTime,endTime,nsServer){
    data = make(map[string]var)
    data["域名"] = domain
    data["注册时间"] = startTime
    data["过期时间"] = endTime
    data["NS服务器"] = nsServer
    yakit.TableData("whois", data)
}

reqRaw = `POST /cgi/qcwss?action=getWhoisInfo&uin=&mc_gtk=&isSkipAuth=1 HTTP/1.1
Host: www.dnspod.cn
Content-Type: application/json; charset=utf-8
User-Agent: Mozilla/5.0 (Linux; Android 9; LYA-AL10 Build/PQ3A.190705.11211812; wv) AppleWebKit/537.36 (KHTML, like Gecko) Version/4.0 Chrome/91.0.4472.114 Mobile Safari/537.36

{"domain":"{{params(domain)}}","api":"getWhoisInfo"}`




sendReq = func(domain){
    wg.Add()
    go fn{
        defer wg.Done()
        res, _, err = poc.HTTP(reqRaw, poc.params({"domain":domain}), poc.https(true),poc.timeout(10))
        if err!= nil{
            die(err)
            return
        }
        _,bodyRaw = poc.Split(res)
        // println(string(bodyRaw))
        resp, err  = str.ParseBytesToHTTPResponse(res)
        if err!= nil{
            log.error("解析数据包失败！")
            die(err)
            return
        }
        if resp.StatusCode != 200{
            log.Info("请求失败！！！")
            return
        }

        dataJson = json.loads(bodyRaw)
        result = dataJson["result"]
        // println(result)
        if result != nil{
            whoisInfo = result["WhoisInfo"]
            if whoisInfo != nil{
                // print(whoisInfo)
                startTime = whoisInfo["RegistrationDate"]
                endTime = whoisInfo["ExpirationDate"]
                nsServer = whoisInfo["DnsServer"]
                if nsServer != nil && len(nsServer) >0{
                    nsServer = str.Join(nsServer, "  ")
                }
                println(nsServer)
                outputTable(domain,startTime,endTime,nsServer)
            }else{
                log.info("%s 获取失败", domain)
            }
        }else{
            log.info("%s 获取失败", domain)
        }

    }
}


for _, domain = range domains{
    sendReq(domain)
}

wg.Wait()

log.info("任务完成--------------------------------------------------------------")
